def _select(xs, k):
    pivot = xs[len(xs) // 2]
    lows = [x for x in xs if x < pivot]
    highs = [x for x in xs if x > pivot]
    same = len(xs) - len(lows) - len(highs)
    if k < len(lows):
        return _select(lows, k)
    if k < len(lows) + same:
        return pivot
    return _select(highs, k - len(lows) - same)

def solve(xs):
    n = len(xs)
    if n % 2:
        return _select(xs, n // 2)
    return (_select(xs, n // 2 - 1) + _select(xs, n // 2)) / 2

